mapper.select:
SELECT q.id, q.quotation_no, q.customer_id, q.quote_date, q.valid_until, q.discount_rate, q.status AS raw_status, AS status, q.order_id, q.order_no, q.submit_time, q.void_time, q.remark, q.create_time, c.code AS customer_code, c.name AS customer_name FROM sal_quotation q LEFT JOIN base_customer c ON c.id = q.customer_id WHERE q.deleted = 0
AND (q.quotation_no LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%'))
AND q.customer_id = #{customerId}
AND q.status = 10 AND q.valid_until < CURDATE()
AND q.status = 10 AND q.valid_until >= CURDATE()
AND q.status = #{status}
AND q.valid_until >= #{validFrom}
AND q.valid_until <= #{validTo}
ORDER BY q.id DESC
